function box(s,n,x,y,w,h,fill=C.pale,geom='rect',stroke='none',sw=0){return s.shapes.add({name:n,geometry:geom,position:{left:x,top:y,width:w,height:h},fill,line:{fill:stroke,width:sw,style:'solid'}});}
